"""Comparison panels open the existing exact source-review requests."""
SCRIPT=r'''
function addPortfolioComparison(box,proposal){
 const panel=N('section'),label=N('label','Hypothetical review slots '),slots=N('input'),button=N('button','Compare review bundles'),out=N('div');slots.type='number';slots.min='0';slots.max='16';slots.value=String(Math.min(3,proposal.counts.requests));slots.setAttribute('aria-label','Hypothetical review slots');label.append(slots);panel.append(N('h3','Compare combinations of review requests'),N('p','One request per slot for this scenario. This is not actual staffing, dollars or a spending limit.','meta'),label,button,out);box.append(panel);
 button.onclick=async()=>{button.disabled=true;out.textContent='Checking exact source dependencies…';try{const r=await semanticFetch('/api/stack/evidence-portfolio/compare',{proposal_id:proposal.id,review_slots:Number(slots.value)});out.replaceChildren();renderEvidencePortfolio(out,r)}catch(e){out.textContent=String(e)}finally{button.disabled=false}};
}
function renderEvidencePortfolio(box,r){
 box.append(N('h2','Evidence-review bundle comparison'),N('p',r.request_count+' distinct requests · '+r.unresolved_check_count+' unresolved documentary checks · '+r.review_slots+' hypothetical review slots','meta'),N('p','A covered check has a complete request set for at least one hypothetical outcome. Review may still leave it unresolved.','missing'),N('p','Each request uses one hypothetical slot. Actual duration, availability and clinical value are unknown.','meta'));
 if(!r.complete){box.append(N('p',r.reason,'warn'),details('Scope and calculation limits',r));return}
 const patients=[...new Set(r.candidate_requests.map(v=>v.patient_id))];if(patients.length===1){const q='Compare evidence-review bundles for patient '+patients[0]+' using contracts '+[...r.contracts].sort().join(',')+' with '+r.review_slots+' review slots.',button=N('button','Run this comparison through the question planner'),status=N('p');button.onclick=async()=>{button.disabled=true;try{$('question').value=q;const result=await semanticFetch('/api/stack/compose',{question:q});renderGraph(result);$('status').textContent='Exact local question plan · '+result.new_paid_api_calls+' paid calls.'}catch(e){status.textContent=String(e)}finally{button.disabled=false}};box.append(button,status)}
 box.append(N('h3',r.optimal.covered_checks+' '+(r.optimal.covered_checks===1?'check':'checks')+' covered by '+r.optimal.slots_used+' '+(r.optimal.slots_used===1?'request':'requests')),N('p','Greedy comparison: '+r.greedy_baseline.covered_checks+' checks with '+r.greedy_baseline.slots_used+' requests. Difference: '+r.baseline_gap+'. No clinical benefit or priority is estimated.'));
 const table=N('table'),head=N('tr');['Available slots','Requests used','Checks covered'].forEach(t=>head.append(N('th',t)));table.append(head);for(const f of r.frontier){const row=N('tr');[f.review_slots,f.slots_used,f.covered_checks].forEach(v=>row.append(N('td',String(v))));table.append(row)}box.append(table);
 if(!r.optimal.request_ids.length)box.append(N('p','No request bundle adds coverage within this scenario.'));
 for(const id of r.optimal.request_ids){const request=r.candidate_requests.find(v=>v.id===id),card=N('section',undefined,'source'),b=N('button','Open source-review request'),out=N('div');card.append(N('h3',request.patient_id+' · '+request.kind.replaceAll('_',' ')),N('p',request.instruction),N('p',[request.detail.field?.replaceAll('_',' '),request.detail.entity,request.detail.dependency?.record_id,request.detail.stream].filter(Boolean).join(' · '),'meta'),N('p',request.requirements.length+' linked documentary checks; this request consumes one slot.','meta'),b,out);box.append(card);b.onclick=async()=>{b.disabled=true;try{const current=await semanticFetch('/api/stack/evidence-portfolio?id='+r.id);if(current.proposal_id!==r.proposal_id)throw Error('Portfolio proposal mismatch');const data=await semanticFetch('/api/stack/evidence-acquisition/item?id='+r.proposal_id+'&item='+id);out.replaceChildren();for(const row of data.requirements){out.append(N('h4',row.contract.title));for(const binding of Object.values(row.bindings))renderRequirementBinding(out,binding);renderResolution(out,await semanticFetch('/api/stack/evidence-resolution?id='+row.id))}out.append(details('Existing source request and receipt',data))}catch(e){out.replaceChildren(N('p',String(e),'warn'))}finally{b.disabled=false}}}
 box.append(N('p','Hypothetical outcomes for different checks may conflict. This count does not establish simultaneous resolution or any patient outcome.','meta'),details('Exact frontier, conditional cases and source receipt',r));
}
'''
